INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'es-b2g-face', id, '2015-01-01', 1, 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html' FROM countries WHERE name_en = 'Spain';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2g-face', 'en', 'B2G e-invoicing mandatory (Ley 25/2013)', 'Invoices to Spanish public bodies must be submitted in Facturae XML format via the FACe platform — a paper invoice or simple PDF is not valid and won''t be processed.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'es-sii-introduced', id, '2017-01-01', 1, 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html' FROM countries WHERE name_en = 'Spain';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-sii-introduced', 'en', 'SII introduced', 'Large taxpayers and monthly filers must send sales and purchase ledgers to AEAT within 4 days, replacing quarterly block reporting with near-real-time visibility. Businesses in SII are outside VeriFactu''s scope.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'es-crea-y-crece-law', id, '2022-01-01', 1, 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html' FROM countries WHERE name_en = 'Spain';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-crea-y-crece-law', 'en', 'Crea y Crece Law enacted (Ley 18/2022)', 'Establishes the legal framework mandating structured B2B e-invoicing — but as a framework law, leaving the technical detail and exact start dates to a future implementing ministerial order.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'es-rrsif-published', id, '2023-12-05', 1, 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html' FROM countries WHERE name_en = 'Spain';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-rrsif-published', 'en', 'Royal Decree 1007/2023 — RRSIF published', 'Sets out the technical requirements for invoicing systems (Reglamento de requisitos de los sistemas informáticos de facturación) underpinning VeriFactu: chained cryptographic hashes, secure timestamps, and electronic signatures to prevent undetected record alteration.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'es-verifactu-corp', id, '2027-01-01', 0, 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html' FROM countries WHERE name_en = 'Spain';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-corp', 'en', 'VeriFactu certified billing software — corporate taxpayers', 'Businesses subject to Corporate Income Tax must use VeriFactu-certified invoicing software (RRSIF) that guarantees the integrity, traceability and immutability of billing records sent to the Agencia Tributaria (AEAT).', '["Confirm your invoicing software is VeriFactu-certified and generates the required hash-chain and QR code", "This is a separate obligation from the broader Crea y Crece B2B e-invoicing mandate below"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'es-verifactu-rest', id, '2027-07-01', 0, 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html' FROM countries WHERE name_en = 'Spain';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-verifactu-rest', 'en', 'VeriFactu mandatory — all other taxpayers', 'The VeriFactu obligation extends to all remaining taxpayers required to keep billing records, including the self-employed and other professionals subject to Personal Income Tax.', '["Self-employed / freelancers: confirm certified billing software is in place well before this date", "Businesses already using the SII real-time reporting system are exempt from VeriFactu"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'es-b2b-large', id, '2027-10-01', 0, 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html' FROM countries WHERE name_en = 'Spain';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-large', 'en', 'Crea y Crece B2B e-invoicing — large businesses (>€8m turnover)', 'Structured B2B e-invoicing becomes mandatory for large businesses under the Crea y Crece law, exchanged via private platforms (with a mandatory copy to the state platform) or the free public solution (SPFE), running alongside VeriFactu.', '["Choose a private e-invoicing platform (must forward a copy to the SPFE) or use the public platform directly", "Confirm EN 16931-compliant formats (UBL, Facturae, CII)", "Report invoice status \u2014 accepted, rejected, or paid \u2014 to AEAT within 4 calendar days"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'es-b2b-all', id, '2028-10-01', 0, 'https://sede.agenciatributaria.gob.es/Sede/iva/sistemas-informaticos-facturacion-verifactu.html' FROM countries WHERE name_en = 'Spain';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('es-b2b-all', 'en', 'Crea y Crece B2B e-invoicing — all remaining businesses', 'The B2B e-invoicing mandate extends to SMEs, sole traders and all other VAT-registered businesses, completing Spain''s dual-track e-invoicing reform.', '["Finalize platform choice and integration well ahead of the deadline", "The final Ministerial Order was still pending as of mid-2026 \u2014 confirm this date closer to the time"]');
